def energy(p):return H*sum(F(a)**2+F(w)**2 for c in CARS for a,w in p['controls'][c])
def trace_stats(plan,path):
 v={c:F(0) for c in CARS};distance={c:F(0) for c in CARS};counts={str(n):0 for n in range(5)};intervals=[];current=None;length=0
 with gzip.open(HERE/path,'rt') as f:
  for text in f:
   row=json.loads(text);active=[]
   for c in CARS:
    nv=F(row['v'][c]);signed=H*(v[c]+nv)/2
    distance[c]+=H*(abs(v[c])+abs(nv))/2 if v[c]*nv>=0 else H*(v[c]*v[c]+nv*nv)/(2*abs(nv-v[c]))
    if signed>=F(1,50):active.append(c)
    v[c]=nv
   n=len(active);counts[str(n)]+=1;k=row['cycle']-1
   if current is None or current['actors']!=active:
    if current:intervals.append(current)
    current={'start':k,'end':k+1,'actors':active,'effective_activity':n}
   else:current['end']=k+1
   length+=1
 if current:intervals.append(current)
